//! The state (thing frame) table, ported from `info.c` (`states`) and
//! `info.h` (`statenum_t`). The vanilla table is generated by the `multigen`
//! utility and is kept here as a plain data table, exactly as shipped.
//!
//! `StateAction` carries only the vanilla action *names*; the bodies live in
//! the gameplay modules (`p_pspr`/`p_enemy` ports) and are attached there by
//! the gameplay agents. No actions are dispatched from this module.

use crate::info::sprites::Sprite;

/// Fullbright flag in a state's `frame` field (vanilla `FF_FULLBRIGHT`,
/// defined in `p_pspr.h`).
pub const FF_FULLBRIGHT: u16 = 0x8000;

