/// One row of the vanilla `states` table (`state_t`), with the
/// `misc1`/`misc2` scratch fields dropped (always `0` in the vanilla
/// table; nothing ever read them back there either).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct State {
    pub sprite: Sprite,
    /// Vanilla `long frame`. Bit 15 ([`FF_FULLBRIGHT`]) marks a fullbright
    /// frame; the rest is the frame number within the sprite.
    pub frame: u16,
    /// Vanilla `long tics`. `-1` means the state runs forever
    /// (see [`State::is_infinite`]).
    pub tics: i16,
    pub action: StateAction,
    pub next: StateId,
}

impl State {
    /// True if the fullbright bit is set in `frame` (vanilla `FF_FULLBRIGHT`).
    pub const fn is_fullbright(&self) -> bool {
        self.frame & FF_FULLBRIGHT != 0
    }

    /// Frame number with the fullbright bit masked out.
    pub const fn frame_index(&self) -> u16 {
        self.frame & !FF_FULLBRIGHT
    }

    /// True for vanilla `tics == -1` (runs forever).
    pub const fn is_infinite(&self) -> bool {
        self.tics == -1
    }
}

