#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn state_count_matches() {
        assert_eq!(StateId::COUNT, 967);
        assert_eq!(STATES.len(), StateId::COUNT);
    }

    #[test]
    fn next_state_stays_in_bounds() {
        for (i, state) in STATES.iter().enumerate() {
            assert!(
                (state.next as usize) < STATES.len(),
                "state {i} next out of range"
            );
        }
    }

    #[test]
    fn null_state_matches_vanilla() {
        let s = &STATES[StateId::S_NULL as usize];
        assert_eq!(s.sprite, Sprite::SPR_TROO);
        assert_eq!(s.frame, 0);
        assert!(s.is_infinite());
        assert_eq!(s.action, StateAction::NoAction);
        assert_eq!(s.next, StateId::S_NULL);
        assert!(!s.is_fullbright());
    }

    #[test]
    fn fullbright_bit_matches_vanilla() {
        // spot checks against info.c: these three frames carry 32768/32769
        let pistol_flash = &STATES[StateId::S_PISTOLFLASH as usize];
        assert_eq!(pistol_flash.frame, 32768);
        assert!(pistol_flash.is_fullbright());
        assert_eq!(pistol_flash.frame_index(), 0);

        let bfg_flash2 = &STATES[StateId::S_BFGFLASH2 as usize];
        assert_eq!(bfg_flash2.frame, 32769);
        assert_eq!(bfg_flash2.frame_index(), 1);

        // every fullbright frame keeps the bit in the raw `frame` field
        assert_eq!(STATES.iter().filter(|s| s.is_fullbright()).count(), 278);
        for s in STATES.iter().filter(|s| s.is_fullbright()) {
            assert_eq!(s.frame & FF_FULLBRIGHT, FF_FULLBRIGHT);
            assert!(s.frame_index() < 0x8000);
        }
    }

    #[test]
    fn action_names_roundtrip() {
        assert_eq!(ACTION_NAMES.len(), StateAction::COUNT);
        assert_eq!(StateAction::NoAction.name(), "NULL");
        assert_eq!(StateAction::A_Light0.name(), "A_Light0");
        // every vanilla state comment was verified against the enum order at port time
        assert_eq!(
            STATES[StateId::S_PUNCH as usize].action,
            StateAction::A_WeaponReady
        );
        assert_eq!(
            STATES[StateId::S_PISTOLFLASH as usize].action,
            StateAction::A_Light1
        );
    }

    #[test]
    fn state_names_roundtrip() {
        assert_eq!(STATE_NAMES.len(), StateId::COUNT);
        assert_eq!(StateId::S_PLAY_RUN1.name(), "S_PLAY_RUN1");
        assert_eq!(StateId::S_NULL.name(), "S_NULL");
        assert_eq!(StateId::S_TECH2LAMP4.name(), "S_TECH2LAMP4");
        for name in STATE_NAMES {
            assert!(name.starts_with("S_"), "bad state name {name}");
        }
    }
}
